// Generated by Cypress Author on 2026-11-11.

// Each attempt passes with this probability. With `retries: 3` (4 attempts total)
// the test ends up passing ~94% of runs, and shows up as flaky whenever it
// needs a retry to get there.
const PASS_RATE = 0.5;

describe("Kitchen sink flaky demo", () => {
  beforeEach(() => {
    cy.visit("/commands/actions");
  });

  it("typing an email → input shows the typed email (intentionally flaky)", () => {
    const passes = Math.random() < PASS_RATE;
    const typed = "fake@email.com";
    const expected = passes ? typed : "wrong@email.com";

    cy.log(`Coin flip: this attempt will ${passes ? "pass" : "fail"}`);

    cy.get("#email1").type(typed);
    cy.get("#email1").should("have.value", expected);
  });
});
